const appts = $input.first().json;
return appts
  .filter(a => a.status === 'confirmado' || a.status === 'pendente')
  .map(a => ({
    json: {
      telefoneCliente: a.clientPhone,
      texto: `Oi, ${a.clientName.split(' ')[0]}! Passando para lembrar do seu horário amanhã às ${new Date(a.startsAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' })}. 💅`
    }
  }));
